package com.tekwatt.invoice.controller;import com.tekwatt.invoice.dto.*;import com.tekwatt.invoice.service.InvoiceService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/invoices")public class InvoiceController{private final InvoiceService service;public InvoiceController(InvoiceService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)InvoiceResponse create(@Valid@RequestBody CreateInvoiceRequest r){return service.create(r);}@GetMapping("/{id}")InvoiceResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping List<InvoiceResponse>list(@RequestParam UUID tenantId){return service.list(tenantId);}@PostMapping("/{id}/issue")InvoiceResponse issue(@PathVariable UUID id){return service.issue(id);}@PostMapping("/{id}/pay")InvoiceResponse pay(@PathVariable UUID id){return service.pay(id);}@PostMapping("/{id}/void")InvoiceResponse voidInvoice(@PathVariable UUID id){return service.voidInvoice(id);}}
